import { useHttp } from "../hooks/http.hook";

const useMarvelService = () => {
  const { request, clearError, process, setProcess } = useHttp();

  const _apiBase = 'https://marvel-server-zeta.vercel.app/';
  const _apiKey = 'apikey=d4eecb0c66dedbfae4eab45d312fc1df';
  const _baseOffset = 0;
  const _baseLimit = 9;

  const getAllCharacters = async (offset = _baseOffset, limit = _baseLimit) => {
    const res = await request(`${_apiBase}characters?limit=${limit}&offset=${offset}&${_apiKey}`);
    return res.data.results.map(_transformCharacter)
  }

  const getCharacter = async (id) => {
    const res = await request(`${_apiBase}characters/${id}?&${_apiKey}`);
    return _transformCharacter(res.data.results[0])
  }

  const getCharacterByName = async (name) => {
    const res = await request(`${_apiBase}characters?name=${name}&${_apiKey}`);
    const results = res.data.results
      .filter(item => item.name.toLowerCase() === name.toLowerCase());

    return results.map(_transformCharacter);
  };

  const getAllComics = async (offset = _baseOffset, limit = _baseLimit) => {
    const res = await request(`${_apiBase}comics?limit=${limit}&offset=${offset}&${_apiKey}`);
    return res.data.results.map(_transformComic)
  }

  const getComic = async (id) => {
    const res = await request(`${_apiBase}comics/${id}?&${_apiKey}`);
    return _transformComic(res.data.results[0])
  }

  const _transformCharacter = (char) => {
    return {
      id: char.id,
      name: char.name,
      description: char.description,
      thumbnail: char.thumbnail.path + '.' + char.thumbnail.extension,
      homepage: char.urls[0].url,
      wiki: char.urls[1].url,
      comics: char.comics.items,
    }
  }

  const _transformComic = (comic) => {
    return {
      id: comic.id,
      title: comic.title,
      description: comic.description,
      pageCount: comic.pageCount,
      thumbnail: comic.thumbnail.path + '.' + comic.thumbnail.extension,
      languages: comic.textObjects.languages,
      price: comic.prices[0].price,
    }
  }

  return {
    process,
    setProcess,
    clearError,
    getAllCharacters,
    getCharacter,
    getCharacterByName,
    getAllComics,
    getComic
  }
}

export default useMarvelService;